const inputItems = $input.all();
let messages = [];
for (const item of inputItems) {
  if (Array.isArray(item.json)) {
    messages.push(...item.json);
  } else if (item.json) {
    messages.push(item.json);
  }
}
const staticData = $getWorkflowStaticData('global');
const lastId = staticData.lastMessageId || null;
if (messages.length) {
  const newest = messages.reduce((m, x) => BigInt(x.id) > BigInt(m) ? x.id : m, messages[0].id);
  staticData.lastMessageId = newest;
}
let newMessages = messages.filter(m => !(m.author && m.author.bot));
if (lastId) {
  newMessages = newMessages.filter(m => BigInt(m.id) > BigInt(lastId));
} else {
  // First run: process up to 10 latest messages
  newMessages = newMessages.slice(0, 10);
}
newMessages.sort((a, b) => BigInt(a.id) > BigInt(b.id) ? 1 : -1);
return newMessages.map(m => ({
  json: {
    messageId: m.id,
    content: m.content || '',
    author: m.author?.username || '',
    attachments: m.attachments || [],
    embeds: m.embeds || []
  }
}));

const cp = require('child_process');

return $input.all().map(item => {
  const json = item.json.body || item.json;
  const content = (json.content || '').trim();
  const messageId = json.messageId || json.id || '';
  const author = json.authorUsername || json.author?.username || json.author || 'DiscordUser';

  const rawUrls = content.match(/https?:\/\/\S+/g) || [];
  const urls = rawUrls.map(u => u.replace(/[)>.,;!?]+$/, ''));
  const hasUrl = urls.length > 0;
  const firstUrl = hasUrl ? urls[0] : '';
  const igMatch = content.match(/https?:\/\/(?:www\.)?instagram\.com\/\S+/i);
  let instagramUrl = urls.find(u => u.includes('instagram.com')) || (igMatch ? igMatch[0].replace(/[)>.,;!?]+$/, '') : '');

  let imageText = "";
  let detectedTitle = "";
  let imdbUrl = "";
  let githubUrl = "";
  let suggestedCategory = "";
  const attachments = json.attachments || [];

  // 1. Process Image Attachments
  for (const att of attachments) {
    const isImage = (att.contentType && att.contentType.startsWith('image/')) ||
                    (att.content_type && att.content_type.startsWith('image/')) ||
                    (att.name && att.name.match(/\.(jpg|jpeg|png|webp|gif)$/i)) ||
                    (att.filename && att.filename.match(/\.(jpg|jpeg|png|webp|gif)$/i)) ||
                    (att.url && att.url.match(/\.(jpg|jpeg|png|webp|gif)/i));

    if (att.url && isImage) {
      try {
        const out = cp.execSync(`python3 /usr/local/bin/analyze_image.py "${att.url}"`, { timeout: 35000 }).toString();
        const res = JSON.parse(out);
        if (res.imageText) {
          imageText += (imageText ? '\n' : '') + res.imageText;
        }
        if (res.detectedTitle && !detectedTitle) {
          detectedTitle = res.detectedTitle;
        }
        if (res.imdbUrl && !imdbUrl) {
          imdbUrl = res.imdbUrl;
        }
      } catch (err) {}
    }
  }

  // 2. Process Plain Text / Non-URL queries via Universal Context Resolver
  if (!hasUrl && (content || imageText)) {
    const queryToResolve = (content || detectedTitle || imageText.split('\n')[0] || '').replace(/["'`]/g, ' ');
    if (queryToResolve.length >= 2) {
      try {
        const out = cp.execSync(`python3 /usr/local/bin/resolve_input_context.py "${queryToResolve}"`, { timeout: 10000 }).toString();
        const res = JSON.parse(out);
        if (res.title && !detectedTitle) detectedTitle = res.title;
        if (res.imdbUrl && !imdbUrl) imdbUrl = res.imdbUrl;
        if (res.githubUrl && !githubUrl) githubUrl = res.githubUrl;
        if (res.suggestedCategory && !suggestedCategory) suggestedCategory = res.suggestedCategory;
      } catch (err) {}
    }
  }

  let fullContent = content;
  if (imageText) {
    fullContent = fullContent ? `${fullContent}\n\n[Extracted Text from Uploaded Image]:\n${imageText}` : `[Extracted Text from Uploaded Image]:\n${imageText}`;
  }

  return {
    json: {
      ...json,
      messageId,
      author,
      content: fullContent,
      urls,
      firstUrl,
      hasUrl,
      instagramUrl,
      imageText,
      scrapedTitle: detectedTitle,
      imdbUrl: imdbUrl,
      githubUrl: githubUrl,
      suggestedCategory: suggestedCategory
    }
  };
});

function chunkMarkdown(text, maxLen = 1850) {
  text = (text || "").trim();
  if (text.length <= maxLen) return [text];

  const chunks = [];
  let remaining = text;

  while (remaining.length > maxLen) {
    let splitIdx = remaining.lastIndexOf('\n\n', maxLen);
    if (splitIdx === -1 || splitIdx < maxLen * 0.4) {
      splitIdx = remaining.lastIndexOf('\n', maxLen);
    }
    if (splitIdx === -1 || splitIdx < maxLen * 0.4) {
      splitIdx = remaining.lastIndexOf('. ', maxLen);
      if (splitIdx !== -1) splitIdx += 1;
    }
    if (splitIdx === -1 || splitIdx < maxLen * 0.4) {
      splitIdx = remaining.lastIndexOf(' ', maxLen);
    }
    if (splitIdx === -1 || splitIdx <= 0) {
      splitIdx = maxLen;
    }

    const chunk = remaining.slice(0, splitIdx).trim();
    if (chunk) chunks.push(chunk);
    remaining = remaining.slice(splitIdx).trim();
  }

  if (remaining) {
    chunks.push(remaining);
  }

  if (chunks.length > 1) {
    return chunks.map((c, i) => `${c}\n\n*(Part ${i + 1}/${chunks.length})*`);
  }
  return chunks;
}

const results = [];
for (const item of $input.all()) {
  const raw = item.json.text ?? item.json.response ?? item.json.output ?? "";
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    parsed = {
      title: "Recipe",
      markdown: raw
    };
  }
  if (!parsed.title) {
    const match = (parsed.markdown || raw).match(/^#\s+(.+)$/m) || (parsed.markdown || raw).match(/^\*\*(.+?)\*\*/m);
    parsed.title = match ? match[1].trim() : "Recipe";
  }

  const markdown = (parsed.markdown || raw).trim();
  const chunks = chunkMarkdown(markdown, 1850);
  for (let i = 0; i < chunks.length; i++) {
    results.push({
      json: {
        ...item.json,
        title: parsed.title,
        markdown: chunks[i],
        finalContent: chunks[i],
        partIndex: i + 1,
        totalParts: chunks.length
      }
    });
  }
}
return results;

