const extractItems = $("Extract URLs").all();
let scrapedItems = [];
try {
  if ($("Parse Instagram (gallery-dl)").isExecuted) {
    scrapedItems = $("Parse Instagram (gallery-dl)").all();
  }
} catch (e) {
  scrapedItems = [];
}

return $input.all().map((item, index) => {
  const text = item.json.text || item.json.response || item.json.output || "";
  let agent = "others";

  try {
    const cleanText = text.replace(/```json/g, "").replace(/```/g, "").trim();
    const parsed = JSON.parse(cleanText);
    if (parsed.agent) {
      agent = parsed.agent.toLowerCase().trim();
    }
  } catch (e) {
    const match = text.match(/"agent"\s*:\s*"([^"]+)"/i) || text.match(/\b(recipe|project|workout|media|anime|others)\b/i);
    if (match) {
      agent = match[1].toLowerCase().trim();
    }
  }

  const currentExtract = (extractItems && extractItems[index]) ? extractItems[index].json : {};
  const isScraped = currentExtract.hasUrl === true;
  const scraped = (isScraped && scrapedItems[index]) ? (scrapedItems[index].json || {}) : {};

  // If Universal Context Resolver identified an entity category with high certainty
  if (currentExtract.suggestedCategory) {
    agent = currentExtract.suggestedCategory;
  }

  const caption = (scraped.caption || currentExtract.caption || currentExtract.content || "").toLowerCase();
  const comments = (scraped.comments || currentExtract.comments || "").toLowerCase();

  // Heuristic Guardrails to prevent TV Series / Movie vs Anime confusion
  const isExplicitLiveAction = (
    caption.includes("series -") ||
    caption.includes("series:") ||
    caption.includes("movie -") ||
    caption.includes("movie:") ||
    caption.includes("film -") ||
    caption.includes("film:") ||
    caption.includes("season 1") ||
    caption.includes("season 2") ||
    caption.includes("season 3") ||
    caption.includes("season 4") ||
    caption.includes("cbfc") ||
    caption.includes("imdb") ||
    caption.includes("netflix") ||
    caption.includes("hbo") ||
    caption.includes("starz") ||
    caption.includes("amazon prime")
  );

  const isExplicitAnimeManga = (
    caption.includes("anime") ||
    caption.includes("manga") ||
    caption.includes("manhwa") ||
    caption.includes("manhua") ||
    caption.includes("webtoon") ||
    caption.includes("donghua") ||
    caption.includes("crunchyroll") ||
    caption.includes("shonen") ||
    caption.includes("seinen") ||
    comments.includes("manhwa name") ||
    comments.includes("manhua name") ||
    comments.includes("webtoon name")
  );

  if (agent === "anime" && isExplicitLiveAction && !isExplicitAnimeManga) {
    agent = "media";
  }

  // Normalize agent aliases
  if (agent === "recipes") agent = "recipe";
  if (agent === "projects") agent = "project";
  if (agent === "workouts") agent = "workout";
  if (agent === "movies" || agent === "movie" || agent === "tv" || agent === "film" || agent === "series") agent = "media";
  if (agent === "manga" || agent === "manhwa" || agent === "manhua" || agent === "webtoon" || agent === "donghua") agent = "anime";

  const validAgents = ["recipe", "project", "workout", "media", "anime", "others"];
  if (!validAgents.includes(agent)) {
    agent = "others";
  }

  return {
    json: {
      ...currentExtract,
      ...scraped,
      agent: agent,
      originalUrl: (currentExtract.urls && currentExtract.urls[0]) || scraped.videoUrl || currentExtract.videoUrl || ""
    }
  };
});

