return $input.all().map(item => {
  const json = item.json;
  const stdout = json.stdout || "";
  let title = "";
  let caption = "";
  let spokenTranscript = "";
  let onScreenText = "";
  let comments = "";
  let githubUrl = "";
  let imdbUrl = "";
  let videoUrl = "";
  let imageUrl = "";
  let author = "";
  let likes = 0;
  let tags = [];
  let sourceType = "";
  let parsedData = null;

  if (stdout.trim()) {
    try {
      const data = JSON.parse(stdout);
      parsedData = data;
      title = data.title || "";
      caption = data.caption || "";
      spokenTranscript = data.spokenTranscript || "";
      onScreenText = data.onScreenText || "";
      comments = data.comments || "";
      githubUrl = data.githubUrl || "";
      imdbUrl = data.imdbUrl || "";
      videoUrl = data.videoUrl || "";
      imageUrl = data.imageUrl || "";
      author = data.author || "";
      likes = data.likes || 0;
      tags = data.tags || [];
      sourceType = data.sourceType || "";
    } catch (e) {}
  }

  return {
    json: {
      ...json,
      scrapedTitle: title,
      caption: caption || "",
      spokenTranscript: spokenTranscript || "",
      onScreenText: onScreenText || "",
      comments: comments || "",
      githubUrl: githubUrl || "",
      imdbUrl: imdbUrl || "",
      videoUrl: videoUrl || (json.urls && json.urls[0]) || "",
      imageUrl: imageUrl || "",
      author: author || "",
